"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["73348"],{48343(e){e.exports=JSON.parse('{"id":"V4-205","slug":"nav-lending","term":"NAV Lending","also_known_as":[],"difficulty":"Advanced","definition":"NAV lending is a type of borrowing in which a private equity or other private markets fund takes out a loan secured against the net asset value of its portfolio of investments.","explanation":["Traditional fund finance, known as subscription lines, is secured against investors\u2019 uncalled commitments and is used early in a fund\u2019s life. NAV loans are typically used later, when the fund has invested most of its money and holds a portfolio of companies.","Funds use NAV loans for several purposes: providing money to support portfolio companies, such as funding acquisitions or refinancing debt; returning money to investors before investments are sold; or bridging gaps when selling companies takes longer than expected.","For example, a fund holding a portfolio valued at 1,000,000,000 might take a NAV loan of 100,000,000, a loan-to-value ratio of 10%, to support several of its companies.","NAV lending has grown rapidly, particularly since 2022, as a slowdown in company sales and stock market listings made it harder for private equity funds to return money to investors.","Critics argue that using NAV loans to make distributions to investors adds leverage and risk, and can make fund performance appear better by returning money earlier. Some institutional investors have asked for greater disclosure and limits on how NAV loans are used."],"note":"","total":1725,"prev":{"slug":"natural-rate-of-unemployment","term":"Natural Rate of Unemployment"},"next":{"slug":"negative-equity","term":"Negative Equity"}}')}}]);